module Top;
  typedef int fixed_t[3];
  typedef struct { int x; byte y; } pair_t;
  typedef pair_t pairs_t[$];
  function automatic fixed_t filled(int v);
    return '{default: v};
  endfunction
  function automatic pairs_t pairs(int v);
    return '{'{v, 1}, '{x: v + 1, y: 2}};
  endfunction
  initial begin
    fixed_t f; pairs_t ps;
    f = filled(7);
    ps = pairs(3);
    $display("[%0d %0d %0d] [%0d %0d %0d %0d]", f[0], f[1], f[2], ps.size(), ps[0].x, ps[1].x, ps[1].y);
  end
endmodule
